values (
  'en-star-wars-original-trilogy-trivia',
  'Star Wars Trivia: The Original Trilogy',
  'Eight questions on Episodes IV to VI: Alderaan, Hoth, Endor, the Millennium Falcon, Yoda and the most famous reveal in cinema.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'movies-tv'),
  '[{"id":"q1","question":"In which year was the first Star Wars film, later subtitled Episode IV: A New Hope, released?","options":[{"id":"a","text":"1975","is_correct":false},{"id":"b","text":"1977","is_correct":true},{"id":"c","text":"1980","is_correct":false},{"id":"d","text":"1983","is_correct":false}],"explanation":"It premiered on 25 May 1977; Episodes V and VI followed in 1980 and 1983."},{"id":"q2","question":"Which peaceful planet does the Death Star destroy in A New Hope?","options":[{"id":"a","text":"Tatooine","is_correct":false},{"id":"b","text":"Alderaan","is_correct":true},{"id":"c","text":"Naboo","is_correct":false},{"id":"d","text":"Endor","is_correct":false}],"explanation":"Grand Moff Tarkin orders Alderaan''s destruction to force Leia to reveal the Rebel base."},{"id":"q3","question":"On which ice planet does the Rebel Alliance hide Echo Base in The Empire Strikes Back?","options":[{"id":"a","text":"Dagobah","is_correct":false},{"id":"b","text":"Bespin","is_correct":false},{"id":"c","text":"Hoth","is_correct":true},{"id":"d","text":"Tatooine","is_correct":false}],"explanation":"The Empire discovers Echo Base with a probe droid and attacks it with AT-AT walkers."},{"id":"q4","question":"What is the name of Han Solo''s freighter?","options":[{"id":"a","text":"The Millennium Falcon","is_correct":true},{"id":"b","text":"Slave I","is_correct":false},{"id":"c","text":"The Tantive IV","is_correct":false},{"id":"d","text":"The Executor","is_correct":false}],"explanation":"According to Han, the Falcon ''made the Kessel Run in less than twelve parsecs''."},{"id":"q5","question":"Which small Jedi Master trains Luke on the swamp planet Dagobah?","options":[{"id":"a","text":"Obi-Wan Kenobi","is_correct":false},{"id":"b","text":"Mace Windu","is_correct":false},{"id":"c","text":"Qui-Gon Jinn","is_correct":false},{"id":"d","text":"Yoda","is_correct":true}],"explanation":"Yoda, exiled on Dagobah, completes the training Obi-Wan started."},{"id":"q6","question":"In Return of the Jedi, which furry creatures help the Rebels on the forest moon of Endor?","options":[{"id":"a","text":"Wookiees","is_correct":false},{"id":"b","text":"Ewoks","is_correct":true},{"id":"c","text":"Jawas","is_correct":false},{"id":"d","text":"Gungans","is_correct":false}],"explanation":"The Ewoks'' primitive tactics help bring down the shield generator protecting the second Death Star."},{"id":"q7","question":"What does Darth Vader reveal to Luke during their duel in The Empire Strikes Back?","options":[{"id":"a","text":"That Leia is his sister","is_correct":false},{"id":"b","text":"That he is Luke''s father","is_correct":true},{"id":"c","text":"That Obi-Wan killed his father","is_correct":false},{"id":"d","text":"That he built C-3PO","is_correct":false}],"explanation":"''No, I am your father'' is one of the most misquoted lines in cinema: Vader never says ''Luke''."},{"id":"q8","question":"Who does Luke learn is his twin sister in Return of the Jedi?","options":[{"id":"a","text":"Padmé Amidala","is_correct":false},{"id":"b","text":"Mon Mothma","is_correct":false},{"id":"c","text":"Rey","is_correct":false},{"id":"d","text":"Princess Leia","is_correct":true}],"explanation":"Yoda confirms there is ''another'' Skywalker; Leia was raised by the Organas of Alderaan."}]'::jsonb,
  null,
  array['star wars', 'trivia', 'original trilogy', 'movies']::text[],
  3,
  'published',
  false,
  false,
  now()
)
