values (
  'es-trivia-trilogia-original-star-wars',
  'Trivia de Star Wars: la trilogía original',
  'Ocho preguntas sobre los episodios IV a VI: Alderaan, Hoth, Endor, el Halcón Milenario, Yoda y la revelación más famosa del cine.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'movies-tv'),
  '[{"id":"q1","question":"¿En qué año se estrenó la primera película de Star Wars, después subtitulada Episodio IV: Una nueva esperanza?","options":[{"id":"a","text":"1975","is_correct":false},{"id":"b","text":"1977","is_correct":true},{"id":"c","text":"1980","is_correct":false},{"id":"d","text":"1983","is_correct":false}],"explanation":"Se estrenó el 25 de mayo de 1977; los episodios V y VI llegaron en 1980 y 1983."},{"id":"q2","question":"¿Qué planeta pacífico destruye la Estrella de la Muerte en Una nueva esperanza?","options":[{"id":"a","text":"Tatooine","is_correct":false},{"id":"b","text":"Alderaan","is_correct":true},{"id":"c","text":"Naboo","is_correct":false},{"id":"d","text":"Endor","is_correct":false}],"explanation":"El gran moff Tarkin ordena la destrucción de Alderaan para obligar a Leia a revelar la base rebelde."},{"id":"q3","question":"¿En qué planeta helado esconde la Alianza Rebelde la Base Eco en El imperio contraataca?","options":[{"id":"a","text":"Dagobah","is_correct":false},{"id":"b","text":"Bespin","is_correct":false},{"id":"c","text":"Hoth","is_correct":true},{"id":"d","text":"Tatooine","is_correct":false}],"explanation":"El Imperio descubre la Base Eco con un droide sonda y la ataca con caminantes AT-AT."},{"id":"q4","question":"¿Cómo se llama el carguero de Han Solo?","options":[{"id":"a","text":"El Halcón Milenario","is_correct":true},{"id":"b","text":"Esclavo I","is_correct":false},{"id":"c","text":"El Tantive IV","is_correct":false},{"id":"d","text":"El Ejecutor","is_correct":false}],"explanation":"Según Han, el Halcón «hizo la carrera de Kessel en menos de doce pársecs»."},{"id":"q5","question":"¿Qué pequeño maestro jedi entrena a Luke en el planeta pantanoso Dagobah?","options":[{"id":"a","text":"Obi-Wan Kenobi","is_correct":false},{"id":"b","text":"Mace Windu","is_correct":false},{"id":"c","text":"Qui-Gon Jinn","is_correct":false},{"id":"d","text":"Yoda","is_correct":true}],"explanation":"Yoda, exiliado en Dagobah, completa el entrenamiento que Obi-Wan comenzó."},{"id":"q6","question":"En El retorno del jedi, ¿qué criaturas peludas ayudan a los rebeldes en la luna forestal de Endor?","options":[{"id":"a","text":"Los wookiees","is_correct":false},{"id":"b","text":"Los ewoks","is_correct":true},{"id":"c","text":"Los jawas","is_correct":false},{"id":"d","text":"Los gungans","is_correct":false}],"explanation":"Las tácticas primitivas de los ewoks ayudan a destruir el generador del escudo de la segunda Estrella de la Muerte."},{"id":"q7","question":"¿Qué le revela Darth Vader a Luke durante su duelo en El imperio contraataca?","options":[{"id":"a","text":"Que Leia es su hermana","is_correct":false},{"id":"b","text":"Que él es el padre de Luke","is_correct":true},{"id":"c","text":"Que Obi-Wan mató a su padre","is_correct":false},{"id":"d","text":"Que él construyó a C-3PO","is_correct":false}],"explanation":"«No, yo soy tu padre» es una de las frases más citadas del cine; Vader nunca dice «Luke»."},{"id":"q8","question":"¿De quién descubre Luke que es su hermana melliza en El retorno del jedi?","options":[{"id":"a","text":"Padmé Amidala","is_correct":false},{"id":"b","text":"Mon Mothma","is_correct":false},{"id":"c","text":"Rey","is_correct":false},{"id":"d","text":"La princesa Leia","is_correct":true}],"explanation":"Yoda confirma que hay «otra» Skywalker; Leia fue criada por los Organa de Alderaan."}]'::jsonb,
