insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-star-wars-prequels-trivia',
  'Star Wars Trivia: The Prequel Trilogy',
  'Eight questions on Episodes I to III: podracing on Tatooine, Darth Maul, the clone army, Order 66 and the duel on Mustafar.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'movies-tv'),
  '[{"id":"q1","question":"In The Phantom Menace, on which planet do Qui-Gon Jinn and his companions find the young Anakin Skywalker?","options":[{"id":"a","text":"Coruscant","is_correct":false},{"id":"b","text":"Naboo","is_correct":false},{"id":"c","text":"Tatooine","is_correct":true},{"id":"d","text":"Kamino","is_correct":false}],"explanation":"Anakin is a slave in Mos Espa, on the same desert world where Luke will grow up."},{"id":"q2","question":"Which Sith apprentice with a double-bladed lightsaber kills Qui-Gon Jinn?","options":[{"id":"a","text":"General Grievous","is_correct":false},{"id":"b","text":"Count Dooku","is_correct":false},{"id":"c","text":"Darth Maul","is_correct":true},{"id":"d","text":"Darth Sidious","is_correct":false}],"explanation":"Obi-Wan avenges his master by cutting Darth Maul in half on Naboo."},{"id":"q3","question":"In Attack of the Clones, on which planet is the secret clone army created?","options":[{"id":"a","text":"Geonosis","is_correct":false},{"id":"b","text":"Kamino","is_correct":true},{"id":"c","text":"Utapau","is_correct":false},{"id":"d","text":"Coruscant","is_correct":false}],"explanation":"Obi-Wan discovers the clones on Kamino; they were commissioned by the Jedi Sifo-Dyas."},{"id":"q4","question":"On which planet''s arena are Anakin, Obi-Wan and Padmé sentenced to die in Attack of the Clones?","options":[{"id":"a","text":"Mustafar","is_correct":false},{"id":"b","text":"Felucia","is_correct":false},{"id":"c","text":"Geonosis","is_correct":true},{"id":"d","text":"Kashyyyk","is_correct":false}],"explanation":"The arrival of the clone army stops the execution in the Petranaki arena: it is the start of the Clone Wars."},{"id":"q5","question":"What secret identity does Chancellor Palpatine reveal to Anakin in Revenge of the Sith?","options":[{"id":"a","text":"That he is the Sith Lord Darth Sidious","is_correct":true},{"id":"b","text":"That he is a clone of the Emperor","is_correct":false},{"id":"c","text":"That he is Anakin''s father","is_correct":false},{"id":"d","text":"That he is a Jedi in hiding","is_correct":false}],"explanation":"The revelation draws Anakin to the dark side in exchange for the promise of saving Padmé."},{"id":"q6","question":"Which order does Palpatine issue to turn the clone troopers against the Jedi?","options":[{"id":"a","text":"Order 99","is_correct":false},{"id":"b","text":"Order 66","is_correct":true},{"id":"c","text":"Directive 7","is_correct":false},{"id":"d","text":"Protocol 13","is_correct":false}],"explanation":"Order 66 triggers the near-extermination of the Jedi across the galaxy."},{"id":"q7","question":"On which volcanic planet do Obi-Wan and Anakin fight their final duel?","options":[{"id":"a","text":"Utapau","is_correct":false},{"id":"b","text":"Geonosis","is_correct":false},{"id":"c","text":"Coruscant","is_correct":false},{"id":"d","text":"Mustafar","is_correct":true}],"explanation":"Anakin is left burned on Mustafar''s lava shore, where he becomes Darth Vader."},{"id":"q8","question":"What are the names of the twins born to Padmé at the end of Revenge of the Sith?","options":[{"id":"a","text":"Luke and Leia","is_correct":true},{"id":"b","text":"Anakin and Ahsoka","is_correct":false},{"id":"c","text":"Ben and Rey","is_correct":false},{"id":"d","text":"Owen and Beru","is_correct":false}],"explanation":"Luke goes to the Lars family on Tatooine and Leia to the Organas of Alderaan."}]'::jsonb,
  null,
  array['star wars', 'trivia', 'prequels', 'movies']::text[],
  3,
  'published',
