insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-star-wars-sequels-trivia',
  'Star Wars Trivia: The Sequel Trilogy',
  'Eight questions on Episodes VII to IX: Rey, Finn, Kylo Ren, BB-8, Starkiller Base and the return of Emperor Palpatine.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'movies-tv'),
  '[{"id":"q1","question":"On which desert planet does Rey live as a scavenger at the start of The Force Awakens?","options":[{"id":"a","text":"Tatooine","is_correct":false},{"id":"b","text":"Jakku","is_correct":true},{"id":"c","text":"Jedha","is_correct":false},{"id":"d","text":"Pasaana","is_correct":false}],"explanation":"Jakku is a different desert world from Tatooine, littered with wrecks of the Galactic Civil War."},{"id":"q2","question":"What is the designation of the stormtrooper who defects and is renamed Finn?","options":[{"id":"a","text":"FN-2187","is_correct":true},{"id":"b","text":"TK-421","is_correct":false},{"id":"c","text":"CT-5555","is_correct":false},{"id":"d","text":"IG-88","is_correct":false}],"explanation":"Poe Dameron gives him the name Finn from his trooper designation."},{"id":"q3","question":"Which spherical droid carries part of the map to Luke Skywalker?","options":[{"id":"a","text":"R2-D2","is_correct":false},{"id":"b","text":"C-3PO","is_correct":false},{"id":"c","text":"BB-8","is_correct":true},{"id":"d","text":"K-2SO","is_correct":false}],"explanation":"BB-8 ends up in Rey''s care after escaping the First Order with Poe."},{"id":"q4","question":"What is Kylo Ren''s birth name?","options":[{"id":"a","text":"Ben Solo","is_correct":true},{"id":"b","text":"Jacen Skywalker","is_correct":false},{"id":"c","text":"Anakin Ren","is_correct":false},{"id":"d","text":"Luke Organa","is_correct":false}],"explanation":"He is the son of Han Solo and Leia Organa, seduced by the dark side."},{"id":"q5","question":"Who kills Han Solo on Starkiller Base in The Force Awakens?","options":[{"id":"a","text":"Captain Phasma","is_correct":false},{"id":"b","text":"General Hux","is_correct":false},{"id":"c","text":"Supreme Leader Snoke","is_correct":false},{"id":"d","text":"Kylo Ren","is_correct":true}],"explanation":"Kylo Ren — his own son — kills Han on a walkway over the base''s reactor shaft."},{"id":"q6","question":"What is the name of the First Order''s planet-sized weapon that destroys star systems?","options":[{"id":"a","text":"The Death Star III","is_correct":false},{"id":"b","text":"Starkiller Base","is_correct":true},{"id":"c","text":"Exegol","is_correct":false},{"id":"d","text":"The Supremacy","is_correct":false}],"explanation":"The Resistance destroys Starkiller Base much like the Rebels destroyed the Death Stars."},{"id":"q7","question":"On which ocean planet does Rey finally find Luke Skywalker?","options":[{"id":"a","text":"Kamino","is_correct":false},{"id":"b","text":"Crait","is_correct":false},{"id":"c","text":"Ahch-To","is_correct":true},{"id":"d","text":"Naboo","is_correct":false}],"explanation":"Luke has exiled himself on Ahch-To, home of the first Jedi temple."},{"id":"q8","question":"In The Rise of Skywalker, who is revealed to be Rey''s grandfather?","options":[{"id":"a","text":"Obi-Wan Kenobi","is_correct":false},{"id":"b","text":"Darth Vader","is_correct":false},{"id":"c","text":"Luke Skywalker","is_correct":false},{"id":"d","text":"Emperor Palpatine","is_correct":true}],"explanation":"Rey is a Palpatine by blood but chooses the name Skywalker at the end."}]'::jsonb,
  null,
  array['star wars', 'trivia', 'sequels', 'movies']::text[],
  3,
