insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-star-wars-characters-trivia',
  'Star Wars Trivia: Heroes, Villains and Droids',
  'Eight questions on the saga''s characters, from Jedi and Sith to bounty hunters, droids and the most-quoted lines of the series.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'movies-tv'),
  '[{"id":"q1","question":"What is the name of the golden protocol droid who claims to be fluent in over six million forms of communication?","options":[{"id":"a","text":"R2-D2","is_correct":false},{"id":"b","text":"C-3PO","is_correct":true},{"id":"c","text":"BB-8","is_correct":false},{"id":"d","text":"K-2SO","is_correct":false}],"explanation":"C-3PO was built by the young Anakin Skywalker on Tatooine."},{"id":"q2","question":"What species is Chewbacca, Han Solo''s co-pilot?","options":[{"id":"a","text":"Ewok","is_correct":false},{"id":"b","text":"Jawa","is_correct":false},{"id":"c","text":"Wookiee","is_correct":true},{"id":"d","text":"Gungan","is_correct":false}],"explanation":"Wookiees come from the forest planet Kashyyyk and communicate with growls."},{"id":"q3","question":"Which bounty hunter in Mandalorian armor tracks down Han Solo in The Empire Strikes Back?","options":[{"id":"a","text":"IG-88","is_correct":false},{"id":"b","text":"Bossk","is_correct":false},{"id":"c","text":"Dengar","is_correct":false},{"id":"d","text":"Boba Fett","is_correct":true}],"explanation":"Boba Fett delivers the carbon-frozen Han to Jabba the Hutt."},{"id":"q4","question":"What color is Mace Windu''s lightsaber, unique among the Jedi of the films?","options":[{"id":"a","text":"Blue","is_correct":false},{"id":"b","text":"Green","is_correct":false},{"id":"c","text":"Purple","is_correct":true},{"id":"d","text":"Yellow","is_correct":false}],"explanation":"Samuel L. Jackson asked for the purple blade so he could spot himself in the Geonosis arena fight."},{"id":"q5","question":"Which Jedi Master takes Anakin Skywalker as his Padawan apprentice?","options":[{"id":"a","text":"Qui-Gon Jinn","is_correct":false},{"id":"b","text":"Obi-Wan Kenobi","is_correct":true},{"id":"c","text":"Yoda","is_correct":false},{"id":"d","text":"Mace Windu","is_correct":false}],"explanation":"Obi-Wan promised his dying master, Qui-Gon Jinn, that he would train Anakin."},{"id":"q6","question":"Which crime lord, a giant slug, holds court in a palace on Tatooine?","options":[{"id":"a","text":"Watto","is_correct":false},{"id":"b","text":"Jabba the Hutt","is_correct":true},{"id":"c","text":"Bib Fortuna","is_correct":false},{"id":"d","text":"Salacious Crumb","is_correct":false}],"explanation":"Jabba meets his end aboard his sail barge during the rescue of Han Solo."},{"id":"q7","question":"Who says the line ''Do. Or do not. There is no try.''?","options":[{"id":"a","text":"Obi-Wan Kenobi","is_correct":false},{"id":"b","text":"Luke Skywalker","is_correct":false},{"id":"c","text":"Qui-Gon Jinn","is_correct":false},{"id":"d","text":"Yoda","is_correct":true}],"explanation":"Yoda says it to Luke in The Empire Strikes Back while teaching him to lift the X-wing."},{"id":"q8","question":"Which smuggler and gambler owned the Millennium Falcon before losing it to Han Solo?","options":[{"id":"a","text":"Lando Calrissian","is_correct":true},{"id":"b","text":"Tobias Beckett","is_correct":false},{"id":"c","text":"Greedo","is_correct":false},{"id":"d","text":"Qi''ra","is_correct":false}],"explanation":"Han won the Falcon from Lando in a game of sabacc, shown in Solo: A Star Wars Story."}]'::jsonb,
  null,
  array['star wars', 'trivia', 'characters', 'jedi']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-personajes-star-wars',
  'Trivia de Star Wars: héroes, villanos y droides',
  'Ocho preguntas sobre los personajes de la saga, de jedi y sith a cazarrecompensas, droides y las frases más citadas de la serie.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'movies-tv'),
  '[{"id":"q1","question":"¿Cómo se llama el droide de protocolo dorado que asegura dominar más de seis millones de formas de comunicación?","options":[{"id":"a","text":"R2-D2","is_correct":false},{"id":"b","text":"C-3PO","is_correct":true},{"id":"c","text":"BB-8","is_correct":false},{"id":"d","text":"K-2SO","is_correct":false}],"explanation":"C-3PO fue construido por el joven Anakin Skywalker en Tatooine."},{"id":"q2","question":"¿De qué especie es Chewbacca, el copiloto de Han Solo?","options":[{"id":"a","text":"Ewok","is_correct":false},{"id":"b","text":"Jawa","is_correct":false},{"id":"c","text":"Wookiee","is_correct":true},{"id":"d","text":"Gungan","is_correct":false}],"explanation":"Los wookiees provienen del planeta boscoso Kashyyyk y se comunican con gruñidos."},{"id":"q3","question":"¿Qué cazarrecompensas con armadura mandaloriana persigue a Han Solo en El imperio contraataca?","options":[{"id":"a","text":"IG-88","is_correct":false},{"id":"b","text":"Bossk","is_correct":false},{"id":"c","text":"Dengar","is_correct":false},{"id":"d","text":"Boba Fett","is_correct":true}],"explanation":"Boba Fett entrega a Han, congelado en carbonita, a Jabba el Hutt."},{"id":"q4","question":"¿De qué color es el sable de luz de Mace Windu, único entre los jedi de las películas?","options":[{"id":"a","text":"Azul","is_correct":false},{"id":"b","text":"Verde","is_correct":false},{"id":"c","text":"Morado","is_correct":true},{"id":"d","text":"Amarillo","is_correct":false}],"explanation":"Samuel L. Jackson pidió la hoja morada para poder ubicarse en la batalla de la arena de Geonosis."},{"id":"q5","question":"¿Qué maestro jedi toma a Anakin Skywalker como aprendiz padawan?","options":[{"id":"a","text":"Qui-Gon Jinn","is_correct":false},{"id":"b","text":"Obi-Wan Kenobi","is_correct":true},{"id":"c","text":"Yoda","is_correct":false},{"id":"d","text":"Mace Windu","is_correct":false}],"explanation":"Obi-Wan prometió a su maestro moribundo, Qui-Gon Jinn, que entrenaría a Anakin."},{"id":"q6","question":"¿Qué señor del crimen, una babosa gigante, tiene su corte en un palacio de Tatooine?","options":[{"id":"a","text":"Watto","is_correct":false},{"id":"b","text":"Jabba el Hutt","is_correct":true},{"id":"c","text":"Bib Fortuna","is_correct":false},{"id":"d","text":"Salacious Crumb","is_correct":false}],"explanation":"Jabba encuentra su fin a bordo de su barcaza durante el rescate de Han Solo."},{"id":"q7","question":"¿Quién dice la frase «Hazlo o no lo hagas, pero no lo intentes»?","options":[{"id":"a","text":"Obi-Wan Kenobi","is_correct":false},{"id":"b","text":"Luke Skywalker","is_correct":false},{"id":"c","text":"Qui-Gon Jinn","is_correct":false},{"id":"d","text":"Yoda","is_correct":true}],"explanation":"Yoda se la dice a Luke en El imperio contraataca mientras le enseña a levantar el Ala-X."},{"id":"q8","question":"¿Qué contrabandista y apostador era dueño del Halcón Milenario antes de perderlo ante Han Solo?","options":[{"id":"a","text":"Lando Calrissian","is_correct":true},{"id":"b","text":"Tobias Beckett","is_correct":false},{"id":"c","text":"Greedo","is_correct":false},{"id":"d","text":"Qi''ra","is_correct":false}],"explanation":"Han le ganó el Halcón a Lando en una partida de sabacc, como se ve en Solo: una historia de Star Wars."}]'::jsonb,
  null,
  array['star wars', 'trivia', 'personajes', 'jedi']::text[],
  3,
  'published',
  false,
  false,
  now()
)
