insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-star-wars-ships-and-planets-trivia',
  'Star Wars Trivia: Ships and Planets',
  'Eight questions on the galaxy''s ships and worlds: the Death Star, X-wings, AT-ATs, Tatooine, Coruscant, Bespin and Kashyyyk.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'movies-tv'),
  '[{"id":"q1","question":"What is the name of the Empire''s moon-sized battle station destroyed in A New Hope?","options":[{"id":"a","text":"The Death Star","is_correct":true},{"id":"b","text":"Starkiller Base","is_correct":false},{"id":"c","text":"The Supremacy","is_correct":false},{"id":"d","text":"The Executor","is_correct":false}],"explanation":"Luke''s proton torpedoes trigger the chain reaction that destroys the first Death Star."},{"id":"q2","question":"Which starfighter does Luke pilot in the trench run against the Death Star?","options":[{"id":"a","text":"A TIE fighter","is_correct":false},{"id":"b","text":"An X-wing","is_correct":true},{"id":"c","text":"A Y-wing","is_correct":false},{"id":"d","text":"An A-wing","is_correct":false}],"explanation":"The Rebel X-wings and Y-wings attack the station''s exposed thermal exhaust port."},{"id":"q3","question":"What is the name of the Empire''s four-legged walking assault vehicle seen on Hoth?","options":[{"id":"a","text":"AT-ST","is_correct":false},{"id":"b","text":"AT-TE","is_correct":false},{"id":"c","text":"AT-AT","is_correct":true},{"id":"d","text":"AT-DP","is_correct":false}],"explanation":"The Rebels trip the AT-ATs by wrapping their legs with tow cables."},{"id":"q4","question":"Which planet is entirely covered by a single city and hosts the galactic capital?","options":[{"id":"a","text":"Naboo","is_correct":false},{"id":"b","text":"Coruscant","is_correct":true},{"id":"c","text":"Corellia","is_correct":false},{"id":"d","text":"Alderaan","is_correct":false}],"explanation":"Coruscant is the seat of both the Republic and, later, the Empire."},{"id":"q5","question":"What does TIE stand for in the name of the Empire''s TIE fighters?","options":[{"id":"a","text":"Tactical Imperial Escort","is_correct":false},{"id":"b","text":"Turbo Ion Engine","is_correct":false},{"id":"c","text":"Twin Ion Engine","is_correct":true},{"id":"d","text":"Turret Imperial Elite","is_correct":false}],"explanation":"The name refers to the fighter''s twin ion engines; the flat side panels are its solar wings."},{"id":"q6","question":"What is the name of the Wookiee homeworld, a planet of giant trees?","options":[{"id":"a","text":"Endor","is_correct":false},{"id":"b","text":"Dagobah","is_correct":false},{"id":"c","text":"Felucia","is_correct":false},{"id":"d","text":"Kashyyyk","is_correct":true}],"explanation":"Kashyyyk appears in Revenge of the Sith during the execution of Order 66."},{"id":"q7","question":"Above which gas giant does Cloud City, run by Lando Calrissian, float?","options":[{"id":"a","text":"Mustafar","is_correct":false},{"id":"b","text":"Bespin","is_correct":true},{"id":"c","text":"Hoth","is_correct":false},{"id":"d","text":"Kamino","is_correct":false}],"explanation":"Han is frozen in carbonite in Cloud City before being taken to Jabba."},{"id":"q8","question":"What is the name of Boba Fett''s distinctive ship?","options":[{"id":"a","text":"The Tantive IV","is_correct":false},{"id":"b","text":"The Millennium Falcon","is_correct":false},{"id":"c","text":"Slave I","is_correct":true},{"id":"d","text":"The Executor","is_correct":false}],"explanation":"Boba Fett inherited Slave I from his father, Jango Fett."}]'::jsonb,
  null,
  array['star wars', 'trivia', 'ships', 'planets']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-naves-y-planetas-star-wars',
  'Trivia de Star Wars: naves y planetas',
  'Ocho preguntas sobre las naves y los mundos de la galaxia: la Estrella de la Muerte, los Ala-X, los AT-AT, Tatooine y Coruscant.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'movies-tv'),
  '[{"id":"q1","question":"¿Cómo se llama la estación de combate del tamaño de una luna del Imperio, destruida en Una nueva esperanza?","options":[{"id":"a","text":"La Estrella de la Muerte","is_correct":true},{"id":"b","text":"La Base Starkiller","is_correct":false},{"id":"c","text":"El Supremacy","is_correct":false},{"id":"d","text":"El Ejecutor","is_correct":false}],"explanation":"Los torpedos de protones de Luke provocan la reacción en cadena que destruye la primera Estrella de la Muerte."},{"id":"q2","question":"¿Qué caza estelar pilotea Luke en la carrera por la trinchera contra la Estrella de la Muerte?","options":[{"id":"a","text":"Un caza TIE","is_correct":false},{"id":"b","text":"Un Ala-X","is_correct":true},{"id":"c","text":"Un Ala-Y","is_correct":false},{"id":"d","text":"Un Ala-A","is_correct":false}],"explanation":"Los Ala-X y Ala-Y rebeldes atacan el puerto de escape térmico expuesto de la estación."},{"id":"q3","question":"¿Cómo se llama el vehículo de asalto caminante de cuatro patas del Imperio, visto en Hoth?","options":[{"id":"a","text":"El AT-ST","is_correct":false},{"id":"b","text":"El AT-TE","is_correct":false},{"id":"c","text":"El AT-AT","is_correct":true},{"id":"d","text":"El AT-DP","is_correct":false}],"explanation":"Los rebeldes derriban los AT-AT enrollando cables en sus patas."},{"id":"q4","question":"¿Qué planeta está cubierto por completo por una sola ciudad y alberga la capital galáctica?","options":[{"id":"a","text":"Naboo","is_correct":false},{"id":"b","text":"Coruscant","is_correct":true},{"id":"c","text":"Corellia","is_correct":false},{"id":"d","text":"Alderaan","is_correct":false}],"explanation":"Coruscant es la sede de la República y, después, del Imperio."},{"id":"q5","question":"¿Qué significa TIE en el nombre de los cazas imperiales?","options":[{"id":"a","text":"Tactical Imperial Escort","is_correct":false},{"id":"b","text":"Turbo Ion Engine","is_correct":false},{"id":"c","text":"Twin Ion Engine","is_correct":true},{"id":"d","text":"Turret Imperial Elite","is_correct":false}],"explanation":"El nombre alude a los motores gemelos de iones del caza; los paneles laterales son sus alas solares."},{"id":"q6","question":"¿Cómo se llama el mundo natal de los wookiees, un planeta de árboles gigantes?","options":[{"id":"a","text":"Endor","is_correct":false},{"id":"b","text":"Dagobah","is_correct":false},{"id":"c","text":"Felucia","is_correct":false},{"id":"d","text":"Kashyyyk","is_correct":true}],"explanation":"Kashyyyk aparece en La venganza de los sith durante la ejecución de la Orden 66."},{"id":"q7","question":"¿Sobre qué gigante gaseoso flota Ciudad Nube, administrada por Lando Calrissian?","options":[{"id":"a","text":"Mustafar","is_correct":false},{"id":"b","text":"Bespin","is_correct":true},{"id":"c","text":"Hoth","is_correct":false},{"id":"d","text":"Kamino","is_correct":false}],"explanation":"Han es congelado en carbonita en Ciudad Nube antes de ser llevado ante Jabba."},{"id":"q8","question":"¿Cómo se llama la característica nave de Boba Fett?","options":[{"id":"a","text":"El Tantive IV","is_correct":false},{"id":"b","text":"El Halcón Milenario","is_correct":false},{"id":"c","text":"Esclavo I","is_correct":true},{"id":"d","text":"El Ejecutor","is_correct":false}],"explanation":"Boba Fett heredó el Esclavo I de su padre, Jango Fett."}]'::jsonb,
  null,
  array['star wars', 'trivia', 'naves', 'planetas']::text[],
  3,
  'published',
